import{_ as a,o as t,c as o,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"설치","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/install"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/install"}],["meta",{"property":"og:title","content":"설치"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/install.md","filePath":"docs/install.md"}'),c={name:"docs/install.md"};function i(d,e,n,p,s,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="설치" tabindex="-1">설치 <a class="header-anchor" href="#설치" aria-label="Permalink to &quot;설치&quot;">​</a></h1><p><a href="https://github.com/proofer-tech/dira/releases/latest" target="_blank" rel="noreferrer">최신 릴리스</a>에서 <code>.dmg</code>를 받아 열고 <code>dira.app</code>을 <code>응용 프로그램</code>으로 끌어다 놓으세요. 업데이트는 앱이 스스로 받습니다.</p><h2 id="필요한-것" tabindex="-1">필요한 것 <a class="header-anchor" href="#필요한-것" aria-label="Permalink to &quot;필요한 것&quot;">​</a></h2><p>준비할 것은 둘입니다. 지금 하나도 없어도 순서대로 따라오시면 됩니다.</p><h3 id="_1-apple-silicon-맥" tabindex="-1">1. Apple Silicon 맥 <a class="header-anchor" href="#_1-apple-silicon-맥" aria-label="Permalink to &quot;1. Apple Silicon 맥&quot;">​</a></h3><p>앱은 여기서만 돕니다. 화면 왼쪽 위 사과 메뉴에서 <code>이 Mac에 관하여</code>를 열어 보세요. <code>칩</code>이 <code>Apple M</code>으로 시작하면 맞습니다. Intel 맥이라면 앱을 쓸 수 없습니다. 그 경우 아래 <a href="#앱-없이-엔진만-쓰기">앱 없이 엔진만 쓰기</a>로 가세요.</p><h3 id="_2-엔진-설정하기" tabindex="-1">2. 엔진 설정하기 <a class="header-anchor" href="#_2-엔진-설정하기" aria-label="Permalink to &quot;2. 엔진 설정하기&quot;">​</a></h3><p>dira가 동작하기 위한 CLI 기반 LLM 엔진이 필요합니다. 워커가 티켓을 물고 띄우는 세션이 이것이라 없으면 티켓이 <code>대기</code>에서 움직이지 않습니다. 기본값은 <a href="https://claude.com/claude-code" target="_blank" rel="noreferrer"><code>claude</code></a>입니다.</p><p>방금 옮겨 놓은 <code>dira.app</code>을 열고 헤더 우측 끝의 톱니(<code>설정</code>)를 누르세요. <code>Claude 인증</code> 섹션의 맨 윗줄을 봐주세요. 깔려 있으면 <code>claude CLI —</code> 뒤에 앱이 찾은 경로가 붙습니다. 없으면 <code>claude CLI를 찾지 못했습니다 — 워커가 세션을 띄우지 못합니다</code>라고 나옵니다.</p><p>엔진을 설치하고 나면 앱을 껐다가 다시 열고 같은 자리를 보세요. 앱이 프로그램을 찾아다닐 경로 목록은 켜질 때 한 번 정해집니다. 그 줄이 경로로 바뀌어 있으면 준비가 끝난 것입니다.</p><p><code>python3</code>와 <code>bash</code>는 macOS에 이미 있습니다. 엔진이 쓰는 것은 그 둘의 표준 라이브러리뿐이라 따로 설치할 패키지가 없습니다.</p><h2 id="앱-없이-엔진만-쓰기" tabindex="-1">앱 없이 엔진만 쓰기 <a class="header-anchor" href="#앱-없이-엔진만-쓰기" aria-label="Permalink to &quot;앱 없이 엔진만 쓰기&quot;">​</a></h2><p>화면이 필요 없거나 Linux에서 돌릴 경우입니다. 이 갈래는 레포를 직접 받습니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/proofer-tech/dira.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Projects/dira</span></span></code></pre></div><p>워커 파일을 손으로 만들고 cron에 거는 절차는 부록 <a href="/docs/cron">엔진만으로 돌리기</a>에 있습니다. 앱을 같이 쓰셔도 상관없습니다. 앱은 자기 몫의 엔진을 번들 안에 따로 들고 있고, 둘 다 같은 큐 루트(<code>&lt;프로젝트&gt;/.dira</code>)만 보고 있으면 서로의 존재를 몰라도 한 프로젝트를 같이 돌봅니다.</p><p>다음은 <a href="/docs/first-ticket">첫 프로젝트 만들기</a>입니다.</p>',16)])])}const g=a(c,[["render",i]]);export{m as __pageData,g as default};
